import { useEffect, useRef, useState } from "react";

const STORAGE_KEY = "trailmap-gear";

const starterGear = [
  { id: "water-bottle", label: "Water bottle", packed: false },
  { id: "trail-snacks", label: "Trail snacks", packed: false },
  { id: "map-compass", label: "Map and compass", packed: false },
  { id: "first-aid", label: "First-aid kit", packed: false },
  { id: "rain-shell", label: "Rain shell", packed: false },
  { id: "warm-layer", label: "Warm layer", packed: false },
  { id: "headlamp", label: "Headlamp", packed: false },
  { id: "sun-protection", label: "Sun protection", packed: false },
];

function getSavedGear() {
  try {
    const savedGear = JSON.parse(localStorage.getItem(STORAGE_KEY));
    const isValid =
      Array.isArray(savedGear) &&
      savedGear.length > 0 &&
      savedGear.every(
        (item) =>
          typeof item.id === "string" &&
          typeof item.label === "string" &&
          typeof item.packed === "boolean",
      );

    return isValid ? savedGear : starterGear;
  } catch {
    return starterGear;
  }
}

function App() {
  const [items, setItems] = useState(getSavedGear);
  const [newItem, setNewItem] = useState("");
  const [formError, setFormError] = useState("");
  const inputRef = useRef(null);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(items));
  }, [items]);

  const packedCount = items.filter((item) => item.packed).length;
  const remainingCount = items.length - packedCount;
  const isReady = items.length > 0 && remainingCount === 0;

  const statusMessage = isReady
    ? "All packed. Trail time."
    : packedCount === 0
      ? "Your trail starts here."
      : `${remainingCount} ${remainingCount === 1 ? "item" : "items"} left to pack.`;

  function toggleItem(id) {
    setItems((currentItems) =>
      currentItems.map((item) =>
        item.id === id ? { ...item, packed: !item.packed } : item,
      ),
    );
  }

  function addItem(event) {
    event.preventDefault();
    const label = newItem.trim();

    if (!label) {
      setFormError("Enter an item before adding it.");
      return;
    }

    const isDuplicate = items.some(
      (item) => item.label.toLowerCase() === label.toLowerCase(),
    );

    if (isDuplicate) {
      setFormError("That item is already on your list.");
      return;
    }

    setItems((currentItems) => [
      ...currentItems,
      { id: `item-${Date.now()}`, label, packed: false },
    ]);
    setNewItem("");
    setFormError("");
    inputRef.current?.focus();
  }

  return (
    <main className="app-shell">
      <section className={`trail-card${isReady ? " is-ready" : ""}`}>
        <header className="trail-header">
          <div>
            <div className="brand-mark" aria-hidden="true">
              TM
            </div>
            <p className="eyebrow">Hiking checklist</p>
            <h1>Trailmap</h1>
            <p className="intro">Pack the essentials. Leave room for the views.</p>
          </div>

          <div className="progress-panel">
            <div className="progress-heading">
              <div>
                <span className="progress-label">Packed</span>
                <strong>
                  {packedCount} <small>of {items.length}</small>
                </strong>
              </div>
              <p aria-live="polite" aria-atomic="true">
                {statusMessage}
              </p>
            </div>
            <progress
              max={items.length || 1}
              value={packedCount}
              aria-label={`${packedCount} of ${items.length} items packed`}
            />
          </div>
        </header>

        <section className="checklist" aria-labelledby="pack-heading">
          <div className="list-heading">
            <h2 id="pack-heading">Your pack</h2>
            <span>{items.length} items</span>
          </div>

          <ul className="gear-list">
            {items.map((item) => (
              <li key={item.id} className={item.packed ? "is-packed" : ""}>
                <input
                  id={item.id}
                  type="checkbox"
                  checked={item.packed}
                  onChange={() => toggleItem(item.id)}
                />
                <label htmlFor={item.id}>{item.label}</label>
              </li>
            ))}
          </ul>

          <form className="add-form" onSubmit={addItem} noValidate>
            <label htmlFor="new-gear">Add to your pack</label>
            <div className="add-row">
              <input
                ref={inputRef}
                id="new-gear"
                name="new-gear"
                type="text"
                value={newItem}
                onChange={(event) => {
                  setNewItem(event.target.value);
                  if (formError) setFormError("");
                }}
                placeholder="e.g. Trekking poles"
                autoComplete="off"
                aria-describedby="form-message"
                aria-invalid={Boolean(formError)}
              />
              <button type="submit">Add item</button>
            </div>
            <p
              id="form-message"
              className={formError ? "form-message is-error" : "form-message"}
              role={formError ? "alert" : undefined}
            >
              {formError || "Saved on this device."}
            </p>
          </form>
        </section>
      </section>
    </main>
  );
}

export default App;

